     1→/**
     2→ * GEDCOM Data Mapper
     3→ * Bidirectional mapping between GEDCOM and Vamsa data models
     4→ */
     5→
     6→import type { GedcomFile } from "./types";
     7→import {
     8→  type MappingResult,
     9→  type MappingError,
    10→  type VamsaPerson,
    11→  type VamsaRelationship,
    12→  type GedcomIndividualData,
    13→  type GedcomFamilyData,
    14→  type MapOptions,
    15→  type ParsedName,
    16→} from "./mapper-types";
    17→import { GedcomParser } from "./parser";
    18→
    19→/**
    20→ * Generate a CUID-like ID for use in mapping operations
    21→ * Uses timestamp + random characters for collision-resistant IDs
    22→ */
    23→function generateId(): string {
    24→  const timestamp = Date.now().toString(36);
    25→  const randomPart = Math.random().toString(36).substring(2, 9);
    26→  return `c${timestamp}${randomPart}`;
    27→}
    28→
    29→export class GedcomMapper {
    30→  private parser: GedcomParser;
    31→
    32→  constructor() {
    33→    this.parser = new GedcomParser();
    34→  }
    35→
    36→  /**
    37→   * Convert parsed GEDCOM data to Vamsa data model
    38→   */
    39→  mapFromGedcom(
    40→    gedcomFile: GedcomFile,
    41→    options?: MapOptions
    42→  ): MappingResult {
    43→    const people: VamsaPerson[] = [];
    44→    const relationships: VamsaRelationship[] = [];
    45→    const errors: MappingError[] = [];
    46→    const warnings: string[] = [];
    47→
    48→    // 1. Validate GEDCOM structure
    49→    if (!options?.skipValidation) {
    50→      const validationErrors = this.parser.validate(gedcomFile);
    51→      for (const error of validationErrors) {
    52→        if (error.severity === "error") {
    53→          errors.push({
    54→            type: "invalid_format",
    55→            source: "INDI",
    56→            id: "unknown",
    57→            field: "structure",
    58→            message: error.message,
    59→          });
    60→        } else {
    61→          warnings.push(error.message);
    62→        }
    63→      }
    64→    }
    65→
    66→    // 2. Create ID mapping (GEDCOM xrefs -> Vamsa CUIDs)
    67→    const idMap = new Map<string, string>();
    68→    for (const individual of gedcomFile.individuals) {
    69→      if (individual.id) {
    70→        idMap.set(individual.id, generateId());
    71→      }
    72→    }
    73→
    74→    // 3. Map individuals (INDI -> Person)
    75→    for (const record of gedcomFile.individuals) {
    76→      if (!record.id) continue;
    77→
    78→      const parsed = this.parser.parseIndividual(record);
    79→      const vamsaId = idMap.get(parsed.id);
    80→
    81→      if (!vamsaId) {
    82→        errors.push({
    83→          type: "missing_data",
    84→          source: "INDI",
    85→          id: parsed.id,
    86→          field: "id",
    87→          message: `Failed to generate ID for individual ${parsed.id}`,
    88→        });
    89→        continue;
    90→      }
    91→
    92→      // Parse name
    93→      const primaryName = parsed.names[0];
    94→      const parsedName = primaryName
    95→        ? this.parseName(primaryName.full)
    96→        : { firstName: "Unknown", lastName: "Unknown" };
    97→
    98→      if (!parsedName.firstName) {
    99→        parsedName.firstName = "Unknown";
   100→      }
   101→      if (!parsedName.lastName) {
   102→        parsedName.lastName = "Unknown";
   103→      }
   104→
   105→      // Determine if person is living
   106→      const isLiving = !parsed.deathDate;
   107→
   108→      // Convert date strings to Date objects
   109→      const dateOfBirth = parsed.birthDate
   110→        ? this.parseISODate(parsed.birthDate)
   111→        : undefined;
   112→      const dateOfPassing = parsed.deathDate
   113→        ? this.parseISODate(parsed.deathDate)
   114→        : undefined;
   115→
   116→      // Map gender
   117→      const gender = this.unmapGender(parsed.sex);
   118→
   119→      const person: VamsaPerson = {
   120→        id: vamsaId,
   121→        firstName: parsedName.firstName,
   122→        lastName: parsedName.lastName,
   123→        dateOfBirth,
   124→        dateOfPassing,
   125→        birthPlace: parsed.birthPlace,
   126→        gender,
   127→        profession: parsed.occupation,
   128→        bio: parsed.notes.join("\n") || undefined,
   129→        isLiving,
   130→      };
   131→
   132→      people.push(person);
   133→    }
   134→
   135→    // 4. Map families (FAM -> Relationships)
   136→    for (const record of gedcomFile.families) {
   137→      if (!record.id) continue;
   138→
   139→      const parsed = this.parser.parseFamily(record);
   140→
   141→      // Create spouse relationships
   142→      if (parsed.husband && parsed.wife) {
   143→        const husbandId = idMap.get(parsed.husband);
   144→        const wifeId = idMap.get(parsed.wife);
   145→
   146→        if (!husbandId || !wifeId) {
   147→          if (!options?.ignoreMissingReferences) {
   148→            errors.push({
   149→              type: "broken_reference",
   150→              source: "FAM",
   151→              id: parsed.id,
   152→              field: "HUSB/WIFE",
   153→              message: `Broken spouse reference in family ${parsed.id}`,
   154→            });
   155→          }
   156→          continue;
   157→        }
   158→
   159→        const marriageDate = parsed.marriageDate
   160→          ? this.parseISODate(parsed.marriageDate)
   161→          : undefined;
   162→        const divorceDate = parsed.divorceDate
   163→          ? this.parseISODate(parsed.divorceDate)
   164→          : undefined;
   165→
   166→        // Create bidirectional SPOUSE relationships
   167→        relationships.push({
   168→          id: generateId(),
   169→          personId: husbandId,
   170→          relatedPersonId: wifeId,
   171→          type: "SPOUSE",
   172→          marriageDate,
   173→          divorceDate,
   174→          isActive: !divorceDate,
   175→        });
   176→
   177→        relationships.push({
   178→          id: generateId(),
   179→          personId: wifeId,
   180→          relatedPersonId: husbandId,
   181→          type: "SPOUSE",
   182→          marriageDate,
   183→          divorceDate,
   184→          isActive: !divorceDate,
   185→        });
   186→      }
   187→
   188→      // Handle same-sex couples - both parents recorded as spouses
   189→      if (parsed.husband && !parsed.wife && parsed.children.length > 0) {
   190→        // Check if there's another family with same husband to infer second spouse
   191→        const otherFamily = gedcomFile.families.find(
   192→          (f) =>
   193→            f.id !== record.id &&
   194→            (this.parser.parseFamily(f).husband === parsed.husband ||
   195→              this.parser.parseFamily(f).wife === parsed.husband)
   196→        );
   197→        if (otherFamily) {
   198→          const otherParsed = this.parser.parseFamily(otherFamily);
   199→          const secondPartner = otherParsed.wife || otherParsed.husband;
   200→          if (secondPartner && secondPartner !== parsed.husband) {
   201→            const husbandId = idMap.get(parsed.husband);
   202→            const secondId = idMap.get(secondPartner);
   203→            if (husbandId && secondId) {
   204→              relationships.push({
   205→                id: generateId(),
   206→                personId: husbandId,
   207→                relatedPersonId: secondId,
   208→                type: "SPOUSE",
   209→                isActive: true,
   210→              });
   211→              relationships.push({
   212→                id: generateId(),
   213→                personId: secondId,
   214→                relatedPersonId: husbandId,
   215→                type: "SPOUSE",
   216→                isActive: true,
   217→              });
   218→            }
   219→          }
   220→        }
   221→      }
   222→
   223→      // Create parent-child relationships
   224→      for (const childId of parsed.children) {
   225→        const childVamsaId = idMap.get(childId);
   226→
   227→        if (!childVamsaId) {
   228→          if (!options?.ignoreMissingReferences) {
   229→            errors.push({
   230→              type: "broken_reference",
   231→              source: "FAM",
   232→              id: parsed.id,
   233→              field: "CHIL",
   234→              message: `Broken child reference in family ${parsed.id}: ${childId}`,
   235→            });
   236→          }
   237→          continue;
   238→        }
   239→
   240→        // PARENT relationships (from parent to child)
   241→        if (parsed.husband) {
   242→          const husbandId = idMap.get(parsed.husband);
   243→          if (husbandId) {
   244→            relationships.push({
   245→              id: generateId(),
   246→              personId: husbandId,
   247→              relatedPersonId: childVamsaId,
   248→              type: "PARENT",
   249→              isActive: true,
   250→            });
   251→          }
   252→        }
   253→
   254→        if (parsed.wife) {
   255→          const wifeId = idMap.get(parsed.wife);
   256→          if (wifeId) {
   257→            relationships.push({
   258→              id: generateId(),
   259→              personId: wifeId,
   260→              relatedPersonId: childVamsaId,
   261→              type: "PARENT",
   262→              isActive: true,
   263→            });
   264→          }
   265→        }
   266→
   267→        // CHILD relationships (from child to parents)
   268→        if (parsed.husband) {
   269→          const husbandId = idMap.get(parsed.husband);
   270→          if (husbandId) {
   271→            relationships.push({
   272→              id: generateId(),
   273→              personId: childVamsaId,
   274→              relatedPersonId: husbandId,
   275→              type: "CHILD",
   276→              isActive: true,
   277→            });
   278→          }
   279→        }
   280→
   281→        if (parsed.wife) {
   282→          const wifeId = idMap.get(parsed.wife);
   283→          if (wifeId) {
   284→            relationships.push({
   285→              id: generateId(),
   286→              personId: childVamsaId,
   287→              relatedPersonId: wifeId,
   288→              type: "CHILD",
   289→              isActive: true,
   290→            });
   291→          }
   292→        }
   293→      }
   294→    }
   295→
   296→    return {
   297→      people,
   298→      relationships,
   299→      errors,
   300→      warnings,
   301→    };
   302→  }
   303→
   304→  /**
   305→   * Convert Vamsa data to GEDCOM format
   306→   */
   307→  mapToGedcom(
   308→    people: VamsaPerson[],
   309→    relationships: VamsaRelationship[]
   310→  ): { individuals: GedcomIndividualData[]; families: GedcomFamilyData[] } {
   311→    const individuals: GedcomIndividualData[] = [];
   312→    const families: GedcomFamilyData[] = [];
   313→
   314→    // Create ID to xref mapping
   315→    const idToXref = new Map<string, string>();
   316→    let individualsIndex = 1;
   317→
   318→    for (const person of people) {
   319→      if (person.id) {
   320→        idToXref.set(person.id, `@I${individualsIndex}@`);
   321→        individualsIndex++;
   322→      }
   323→    }
   324→
   325→    // Create individuals
   326→    for (const person of people) {
   327→      if (!person.id) continue;
   328→
   329→      const xref = idToXref.get(person.id);
   330→      if (!xref) continue;
   331→
   332→      const name = this.formatName(person.firstName, person.lastName);
   333→      const sex = this.mapGender(person.gender);
   334→
   335→      const individual: GedcomIndividualData = {
   336→        xref,
   337→        name,
   338→        sex,
   339→        birthDate: person.dateOfBirth
   340→          ? this.formatToGedcomDate(person.dateOfBirth)
   341→          : undefined,
   342→        birthPlace: person.birthPlace,
   343→        deathDate: person.dateOfPassing
   344→          ? this.formatToGedcomDate(person.dateOfPassing)
   345→          : undefined,
   346→        occupation: person.profession,
   347→        notes: person.bio ? [person.bio] : [],
   348→        familiesAsSpouse: [],
   349→        familiesAsChild: [],
   350→      };
   351→
   352→      individuals.push(individual);
   353→    }
   354→
   355→    // Build family structures from relationships
   356→    const familyMap = new Map<
   357→      string,
   358→      {
   359→        spouses: [string, string] | [string] | undefined;
   360→        children: string[];
   361→        marriages: Map<string, { marriageDate?: Date; divorceDate?: Date }>;
   362→      }
   363→    >();
   364→
   365→    // Group relationships by family units
   366→    for (const rel of relationships) {
   367→      if (rel.type === "SPOUSE") {
   368→        // Find or create family for this couple
   369→        let familyKey = `${rel.personId}-${rel.relatedPersonId}`;
   370→        let reverseKey = `${rel.relatedPersonId}-${rel.personId}`;
   371→
   372→        // Check if we already have this couple in reverse order
   373→        if (familyMap.has(reverseKey) && !familyMap.has(familyKey)) {
   374→          familyKey = reverseKey;
   375→        }
   376→
   377→        if (!familyMap.has(familyKey)) {
   378→          familyMap.set(familyKey, {
   379→            spouses: [rel.personId, rel.relatedPersonId] as [string, string],
   380→            children: [],
   381→            marriages: new Map(),
   382→          });
   383→        }
   384→
   385→        const family = familyMap.get(familyKey);
   386→        if (family && rel.marriageDate) {
   387→          const key = `${rel.personId}-${rel.relatedPersonId}`;
   388→          family.marriages.set(key, {
   389→            marriageDate: rel.marriageDate,
   390→            divorceDate: rel.divorceDate,
   391→          });
   392→        }
   393→      }
   394→    }
   395→
   396→    // Add children to families
   397→    for (const rel of relationships) {
   398→      if (rel.type === "PARENT") {
   399→        // Find family with this parent
   400→        for (const [, family] of familyMap.entries()) {
   401→          if (
   402→            family.spouses &&
   403→            (family.spouses[0] === rel.personId ||
   404→              family.spouses[1] === rel.personId)
   405→          ) {
   406→            if (!family.children.includes(rel.relatedPersonId)) {
   407→              family.children.push(rel.relatedPersonId);
   408→            }
   409→          }
   410→        }
   411→      }
   412→    }
   413→
   414→    // Create FAM records
   415→    let familyIndex = 1;
   416→    for (const [, family] of familyMap.entries()) {
   417→      if (!family.spouses) continue;
   418→
   419→      const xref = `@F${familyIndex}@`;
   420→      familyIndex++;
   421→
   422→      const husband =
   423→        family.spouses && family.spouses.length > 0
   424→          ? idToXref.get(family.spouses[0] || "")
   425→          : undefined;
   426→      const wife =
   427→        family.spouses && family.spouses.length > 1
   428→          ? idToXref.get((family.spouses as [string, string])[1])
   429→          : undefined;
   430→
   431→      const children = family.children
   432→        .map((childId) => idToXref.get(childId))
   433→        .filter((x): x is string => !!x);
   434→
   435→      // Get marriage dates from relationship
   436→      let marriageDate: string | undefined;
   437→      let divorceDate: string | undefined;
   438→
   439→      for (const [, marriage] of family.marriages.entries()) {
   440→        if (marriage.marriageDate) {
   441→          marriageDate = this.formatToGedcomDate(marriage.marriageDate);
   442→        }
   443→        if (marriage.divorceDate) {
   444→          divorceDate = this.formatToGedcomDate(marriage.divorceDate);
   445→        }
   446→      }
   447→
   448→      const familyData: GedcomFamilyData = {
   449→        xref,
   450→        husband,
   451→        wife,
   452→        children,
   453→        marriageDate,
   454→        divorceDate,
   455→        notes: [],
   456→      };
   457→
   458→      families.push(familyData);
   459→
   460→      // Update individuals with family references
   461→      for (const individual of individuals) {
   462→        if (individual.xref === husband || individual.xref === wife) {
   463→          individual.familiesAsSpouse.push(xref);
   464→        }
   465→        if (children.includes(individual.xref)) {
   466→          individual.familiesAsChild.push(xref);
   467→        }
   468→      }
   469→    }
   470→
   471→    return { individuals, families };
   472→  }
   473→
   474→  /**
   475→   * Parse GEDCOM name format
   476→   * Format: "Given /Surname/" or "Given" or "/Surname/"
   477→   */
   478→  private parseName(gedcomName: string): ParsedName {
   479→    if (!gedcomName || !gedcomName.trim()) {
   480→      return {};
   481→    }
   482→
   483→    const trimmed = gedcomName.trim();
   484→
   485→    // Find surname between forward slashes
   486→    const surnameMatch = trimmed.match(/\/([^\/]*)\//);
   487→    const lastName = surnameMatch ? surnameMatch[1].trim() : undefined;
   488→
   489→    // Extract given names (everything before and after surname)
   490→    let firstName: string | undefined;
   491→    if (surnameMatch) {
   492→      // Remove the /surname/ part and trim
   493→      const withoutSurname = trimmed
   494→        .replace(/\/[^\/]*\//, "")
   495→        .trim();
   496→      firstName = withoutSurname || undefined;
   497→    } else {
   498→      // No surname markers, entire thing is given name
   499→      firstName = trimmed || undefined;
   500→    }
   501→
   502→    return {
   503→      firstName: firstName || undefined,
   504→      lastName: lastName || undefined,
   505→    };
   506→  }
   507→
   508→  /**
   509→   * Format name to GEDCOM style
   510→   */
   511→  private formatName(firstName: string, lastName?: string): string {
   512→    if (!lastName) {
   513→      return firstName || "";
   514→    }
   515→    return `${firstName} /${lastName}/`;
   516→  }
   517→
   518→  /**
   519→   * Map Vamsa gender to GEDCOM
   520→   */
   521→  private mapGender(
   522→    vamsaGender?: string | null
   523→  ): "M" | "F" | "X" | undefined {
   524→    if (!vamsaGender) return undefined;
   525→    switch (vamsaGender) {
   526→      case "MALE":
   527→        return "M";
   528→      case "FEMALE":
   529→        return "F";
   530→      case "OTHER":
   531→        return "X";
   532→      default:
   533→        return undefined;
   534→    }
   535→  }
   536→
   537→  /**
   538→   * Map GEDCOM gender to Vamsa
   539→   */
   540→  private unmapGender(
   541→    gedcomGender?: string
   542→  ): "MALE" | "FEMALE" | "OTHER" | undefined {
   543→    if (!gedcomGender) return undefined;
   544→    switch (gedcomGender) {
   545→      case "M":
   546→        return "MALE";
   547→      case "F":
   548→        return "FEMALE";
   549→      case "X":
   550→        return "OTHER";
   551→      default:
   552→        return undefined;
   553→    }
   554→  }
   555→
   556→  /**
   557→   * Parse ISO date string (YYYY-MM-DD) to Date object
   558→   */
   559→  private parseISODate(isoDateString: string): Date | undefined {
   560→    if (!isoDateString) return undefined;
   561→
   562→    try {
   563→      // Parse ISO date and create UTC date at midnight
   564→      const parts = isoDateString.split("-");
   565→      if (parts.length < 1) return undefined;
   566→
   567→      const year = parseInt(parts[0], 10);
   568→      const month = parts.length > 1 ? parseInt(parts[1], 10) - 1 : 0; // month is 0-based
   569→      const day = parts.length > 2 ? parseInt(parts[2], 10) : 1;
   570→
   571→      // Create date at UTC midnight
   572→      return new Date(Date.UTC(year, month, day, 0, 0, 0, 0));
   573→    } catch {
   574→      return undefined;
   575→    }
   576→  }
   577→
   578→  /**
   579→   * Format Date to GEDCOM format
   580→   * Returns "DD MMM YYYY" for full dates
   581→   */
   582→  private formatToGedcomDate(date: Date): string {
   583→    if (!date) return "";
   584→
   585→    const monthNames = [
   586→      "JAN",
   587→      "FEB",
   588→      "MAR",
   589→      "APR",
   590→      "MAY",
   591→      "JUN",
   592→      "JUL",
   593→      "AUG",
   594→      "SEP",
   595→      "OCT",
   596→      "NOV",
   597→      "DEC",
   598→    ];
   599→
   600→    const year = date.getUTCFullYear();
   601→    const month = monthNames[date.getUTCMonth()];
   602→    const day = date.getUTCDate();
   603→
   604→    return `${day} ${month} ${year}`;
   605→  }
   606→}
   607→
   608→export type {
   609→  MappingResult,
   610→  MappingError,
   611→  VamsaPerson,
   612→  VamsaRelationship,
   613→  GedcomIndividualData,
   614→  GedcomFamilyData,
   615→  MapOptions,
   616→};
   617→

