     1→import { describe, it, expect } from "bun:test";
     2→import { GedcomParser } from "./parser";
     3→import { GedcomMapper } from "./mapper";
     4→
     5→describe("GedcomMapper", () => {
     6→  const parser = new GedcomParser();
     7→  const mapper = new GedcomMapper();
     8→
     9→  const sampleGedcom = `0 HEAD
    10→1 SOUR MyApp
    11→1 VERS 5.5.1
    12→1 CHAR UTF-8
    13→1 GEDC
    14→2 VERS 5.5.1
    15→0 @I1@ INDI
    16→1 NAME John /Smith/
    17→1 SEX M
    18→1 BIRT
    19→2 DATE 15 JAN 1985
    20→2 PLAC New York, NY
    21→1 OCCU Engineer
    22→1 NOTE This is a note
    23→1 FAMS @F1@
    24→0 @I2@ INDI
    25→1 NAME Jane /Smith/
    26→1 SEX F
    27→1 BIRT
    28→2 DATE 10 JAN 1988
    29→2 PLAC Boston, MA
    30→1 FAMS @F1@
    31→0 @I3@ INDI
    32→1 NAME Robert /Smith/
    33→1 SEX M
    34→1 BIRT
    35→2 DATE 1990
    36→1 FAMC @F1@
    37→0 @F1@ FAM
    38→1 HUSB @I1@
    39→1 WIFE @I2@
    40→1 CHIL @I3@
    41→1 MARR
    42→2 DATE 10 JUN 1985
    43→2 PLAC Boston, MA
    44→0 TRLR`;
    45→
    46→  const gedcomWithDeathDate = `0 HEAD
    47→1 SOUR MyApp
    48→1 VERS 5.5.1
    49→1 CHAR UTF-8
    50→1 GEDC
    51→2 VERS 5.5.1
    52→0 @I1@ INDI
    53→1 NAME John /Smith/
    54→1 SEX M
    55→1 BIRT
    56→2 DATE 15 JAN 1900
    57→1 DEAT
    58→2 DATE 10 JUN 1985
    59→0 @I2@ INDI
    60→1 NAME Jane /Smith/
    61→1 SEX F
    62→1 BIRT
    63→2 DATE 10 JAN 1905
    64→0 TRLR`;
    65→
    66→  const gedcomWithSameSexCouple = `0 HEAD
    67→1 SOUR MyApp
    68→1 VERS 5.5.1
    69→1 CHAR UTF-8
    70→1 GEDC
    71→2 VERS 5.5.1
    72→0 @I1@ INDI
    73→1 NAME John /Smith/
    74→1 SEX M
    75→0 @I2@ INDI
    76→1 NAME Michael /Johnson/
    77→1 SEX M
    78→0 @I3@ INDI
    79→1 NAME David /Smith-Johnson/
    80→1 SEX M
    81→1 FAMC @F1@
    82→0 @F1@ FAM
    83→1 HUSB @I1@
    84→1 CHIL @I3@
    85→0 @F2@ FAM
    86→1 HUSB @I2@
    87→1 CHIL @I3@
    88→0 TRLR`;
    89→
    90→  const gedcomWithDivorce = `0 HEAD
    91→1 SOUR MyApp
    92→1 VERS 5.5.1
    93→1 CHAR UTF-8
    94→1 GEDC
    95→2 VERS 5.5.1
    96→0 @I1@ INDI
    97→1 NAME John /Smith/
    98→1 SEX M
    99→1 FAMS @F1@
   100→0 @I2@ INDI
   101→1 NAME Jane /Smith/
   102→1 SEX F
   103→1 FAMS @F1@
   104→0 @F1@ FAM
   105→1 HUSB @I1@
   106→1 WIFE @I2@
   107→1 MARR
   108→2 DATE 10 JUN 1985
   109→1 DIV
   110→2 DATE 01 JAN 2000
   111→0 TRLR`;
   112→
   113→  describe("mapFromGedcom", () => {
   114→    it("should map individuals with all fields", () => {
   115→      const gedcomFile = parser.parse(sampleGedcom);
   116→      const result = mapper.mapFromGedcom(gedcomFile);
   117→
   118→      expect(result.people).toHaveLength(3);
   119→
   120→      const john = result.people[0];
   121→      expect(john.firstName).toBe("John");
   122→      expect(john.lastName).toBe("Smith");
   123→      expect(john.gender).toBe("MALE");
   124→      expect(john.profession).toBe("Engineer");
   125→      expect(john.isLiving).toBe(true);
   126→      expect(john.birthPlace).toBe("New York, NY");
   127→    });
   128→
   129→    it("should parse birth dates correctly", () => {
   130→      const gedcomFile = parser.parse(sampleGedcom);
   131→      const result = mapper.mapFromGedcom(gedcomFile);
   132→
   133→      const john = result.people[0];
   134→      expect(john.dateOfBirth).toBeDefined();
   135→      expect(john.dateOfBirth?.getUTCFullYear()).toBe(1985);
   136→      expect(john.dateOfBirth?.getUTCMonth()).toBe(0); // January is 0
   137→      expect(john.dateOfBirth?.getUTCDate()).toBe(15);
   138→    });
   139→
   140→    it("should map female gender correctly", () => {
   141→      const gedcomFile = parser.parse(sampleGedcom);
   142→      const result = mapper.mapFromGedcom(gedcomFile);
   143→
   144→      const jane = result.people[1];
   145→      expect(jane.gender).toBe("FEMALE");
   146→    });
   147→
   148→    it("should handle partial birth dates", () => {
   149→      const gedcomFile = parser.parse(sampleGedcom);
   150→      const result = mapper.mapFromGedcom(gedcomFile);
   151→
   152→      const robert = result.people[2];
   153→      expect(robert.dateOfBirth?.getUTCFullYear()).toBe(1990);
   154→    });
   155→
   156→    it("should set isLiving based on death date", () => {
   157→      const gedcomFile = parser.parse(gedcomWithDeathDate);
   158→      const result = mapper.mapFromGedcom(gedcomFile);
   159→
   160→      const john = result.people[0];
   161→      expect(john.isLiving).toBe(false);
   162→      expect(john.dateOfPassing).toBeDefined();
   163→
   164→      const jane = result.people[1];
   165→      expect(jane.isLiving).toBe(true);
   166→    });
   167→
   168→    it("should combine notes into bio", () => {
   169→      const gedcomFile = parser.parse(sampleGedcom);
   170→      const result = mapper.mapFromGedcom(gedcomFile);
   171→
   172→      const john = result.people[0];
   173→      expect(john.bio).toContain("This is a note");
   174→    });
   175→
   176→    it("should create spouse relationships", () => {
   177→      const gedcomFile = parser.parse(sampleGedcom);
   178→      const result = mapper.mapFromGedcom(gedcomFile);
   179→
   180→      const spouseRels = result.relationships.filter(
   181→        (r) => r.type === "SPOUSE"
   182→      );
   183→      expect(spouseRels).toHaveLength(2); // Bidirectional
   184→    });
   185→
   186→    it("should create parent-child relationships", () => {
   187→      const gedcomFile = parser.parse(sampleGedcom);
   188→      const result = mapper.mapFromGedcom(gedcomFile);
   189→
   190→      const parentRels = result.relationships.filter(
   191→        (r) => r.type === "PARENT"
   192→      );
   193→      const childRels = result.relationships.filter((r) => r.type === "CHILD");
   194→
   195→      expect(parentRels.length).toBeGreaterThan(0);
   196→      expect(childRels.length).toBeGreaterThan(0);
   197→    });
   198→
   199→    it("should parse marriage dates", () => {
   200→      const gedcomFile = parser.parse(sampleGedcom);
   201→      const result = mapper.mapFromGedcom(gedcomFile);
   202→
   203→      const spouseRels = result.relationships.filter(
   204→        (r) => r.type === "SPOUSE"
   205→      );
   206→      const rel = spouseRels[0];
   207→
   208→      expect(rel.marriageDate).toBeDefined();
   209→      expect(rel.marriageDate?.getUTCFullYear()).toBe(1985);
   210→      expect(rel.marriageDate?.getUTCMonth()).toBe(5); // June
   211→      expect(rel.marriageDate?.getUTCDate()).toBe(10);
   212→    });
   213→
   214→    it("should handle divorce dates", () => {
   215→      const gedcomFile = parser.parse(gedcomWithDivorce);
   216→      const result = mapper.mapFromGedcom(gedcomFile);
   217→
   218→      const spouseRels = result.relationships.filter(
   219→        (r) => r.type === "SPOUSE"
   220→      );
   221→      expect(spouseRels[0].divorceDate).toBeDefined();
   222→      expect(spouseRels[0].divorceDate?.getUTCFullYear()).toBe(2000);
   223→      expect(spouseRels[0].isActive).toBe(false);
   224→    });
   225→
   226→    it("should generate unique IDs for all people", () => {
   227→      const gedcomFile = parser.parse(sampleGedcom);
   228→      const result = mapper.mapFromGedcom(gedcomFile);
   229→
   230→      const ids = result.people.map((p) => p.id);
   231→      const uniqueIds = new Set(ids);
   232→      expect(uniqueIds.size).toBe(ids.length);
   233→    });
   234→
   235→    it("should generate unique IDs for all relationships", () => {
   236→      const gedcomFile = parser.parse(sampleGedcom);
   237→      const result = mapper.mapFromGedcom(gedcomFile);
   238→
   239→      const ids = result.relationships.map((r) => r.id);
   240→      const uniqueIds = new Set(ids);
   241→      expect(uniqueIds.size).toBe(ids.length);
   242→    });
   243→  });
   244→
   245→  describe("mapToGedcom", () => {
   246→    it("should map persons to GEDCOM individuals", () => {
   247→      const gedcomFile = parser.parse(sampleGedcom);
   248→      const mapResult = mapper.mapFromGedcom(gedcomFile);
   249→      const gedcomResult = mapper.mapToGedcom(
   250→        mapResult.people,
   251→        mapResult.relationships
   252→      );
   253→
   254→      expect(gedcomResult.individuals).toHaveLength(3);
   255→    });
   256→
   257→    it("should format names correctly", () => {
   258→      const gedcomFile = parser.parse(sampleGedcom);
   259→      const mapResult = mapper.mapFromGedcom(gedcomFile);
   260→      const gedcomResult = mapper.mapToGedcom(
